import React, { lazy } from "react";
import { Switch, Route, Redirect } from "react-router-dom";

import { APP_PREFIX_PATH } from "configs/AppConfig";

const PortalUsers = () => {
  return (
    <Switch>
      <Redirect
        exact
        from={`${APP_PREFIX_PATH}/portal-users`}
        to={`${APP_PREFIX_PATH}/portal-users/list`}
      />

      <Route
        path={`${APP_PREFIX_PATH}/portal-users/list`}
        component={lazy(() => import(`./portal-users-list`))}
      />
      <Route
        path={`${APP_PREFIX_PATH}/portal-users/view/:id`}
        component={lazy(() => import(`./portal-users-list`))}
      />
    </Switch>
  );
};

export default PortalUsers;
